#[inline]
fn destack_os_lifecycle_close_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::BindingContext<'_>,
    world: RuntimeWorld,
    handle: resource::LifecycleEventHandle,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        OS_LIFECYCLE_CLOSE,
        binding.replay_payload_for(OS_LIFECYCLE_CLOSE)?,
        context,
        |context| match world {
            RuntimeWorld::Host => platform_vm::destack_os_lifecycle_close(binding, context, handle),
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_os_lifecycle_close(binding, context, handle)
            }
        },
        |_context, result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = OsLifecycleCloseReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    OsLifecycleCloseReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_os_lifecycle_close_result(context, result)?;
    Ok(result)
}

#[inline]
fn destack_os_lifecycle_open_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::BindingContext<'_>,
    world: RuntimeWorld,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        OS_LIFECYCLE_OPEN,
        binding.replay_payload_for(OS_LIFECYCLE_OPEN)?,
        context,
        |context| match world {
            RuntimeWorld::Host => platform_vm::destack_os_lifecycle_open(binding, context),
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_os_lifecycle_open(binding, context)
            }
        },
        |_context, result| {
            if let Ok(value) = result {
                let result_value: resource::LifecycleEventHandle = value.clone();
                let result_recorded = result_value;
                let payload = OsLifecycleOpenReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    OsLifecycleOpenReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result = value;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_os_lifecycle_open_result(context, result)?;
    Ok(result)
}

