#[inline]
fn destack_os_lifecycle_state_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::BindingContext<'_>,
    world: RuntimeWorld,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        OS_LIFECYCLE_STATE,
        binding.replay_payload_for(OS_LIFECYCLE_STATE)?,
        context,
        |context| match world {
            RuntimeWorld::Host => platform_vm::destack_os_lifecycle_state(binding, context),
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_os_lifecycle_state(binding, context)
            }
        },
        |_context, result| {
            if let Ok(value) = result {
                let result_value: LifecycleState = value.clone();
                let result_recorded = result_value;
                let payload = OsLifecycleStateReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    OsLifecycleStateReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result = value;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_os_lifecycle_state_result(context, result)?;
    Ok(result)
}

